          <div data-ref="bellDotRef" style="position:absolute;top:9px;right:11px;width:9px;height:9px;border-radius:50%;background:#E31E24;border:2px solid #fff;box-shadow:0 0 6px rgba(227,30,36,.6);display:${a._showBellDot};"></div>
